Implement RingBuffer<T> in src/lib.rs.

pub struct RingBuffer<T> {
    buf: Vec<Option<T>>,
    head: usize,  // index of next pop
    tail: usize,  // index of next push
    len: usize,
    cap: usize,
}

impl<T> RingBuffer<T> {
    pub fn new(cap: usize) -> Self {
        let buf = (0..cap).map(|_| None).collect();
        RingBuffer { buf, head: 0, tail: 0, len: 0, cap }
    }

    pub fn push(&mut self, val: T) {
        if self.len == self.cap {
            // Overwrite oldest: advance head
            self.head = (self.head + 1) % self.cap;
        } else {
            self.len += 1;
        }
        self.buf[self.tail] = Some(val);
        self.tail = (self.tail + 1) % self.cap;
    }

    pub fn pop(&mut self) -> Option<T> {
        if self.len == 0 { return None; }
        let val = self.buf[self.head].take();
        self.head = (self.head + 1) % self.cap;
        self.len -= 1;
        val
    }

    pub fn len(&self) -> usize { self.len }
    pub fn is_full(&self) -> bool { self.len == self.cap }
}

All 5 tests must pass.
Run: cargo test
